files.tiles/fetch.py:
"""Download one map tile from its source."""
import urllib.request


def fetch_tile(source, z, x, y, timeout=5.0):
    url = source["url"].format(z=z, x=x, y=y)
    with urllib.request.urlopen(url, timeout=timeout) as r:
        return r.read()

